const LOGO='data:image/png;base64,';
const $=s=>document.querySelector(s);
const KEY='legions_v1',CATS=['Junior','Senior'];
let db=JSON.parse(localStorage.getItem(KEY)||'{"players":[],"rec":{}}');
let cat='Junior',view='att',editId=null,photoData='';
let gotP=false;const cloudOn=()=>window.Cloud&&Cloud.on;
const save=()=>{if(!cloudOn())localStorage.setItem(KEY,JSON.stringify(db))};
const sync=()=>{if(cloudOn())Cloud.saveSession($('#date').value,cat,db.rec[rk()]||{})};
const today=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,10)};
$('#date').value=today();
const rk=(d=$('#date').value,c=cat)=>d+'|'+c;
const fmt=d=>new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const logo=LOGO;
const plist=c=>db.players.filter(p=>p.cat===c).sort((a,b)=>a.name.localeCompare(b.name));
const initials=n=>n.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()||'?';
const avatar=p=>p.photo?`<img class="ini" src="${p.photo}" data-i="${esc(initials(p.name))}" onerror="this.outerHTML='<div class=ini>'+this.dataset.i+'</div>'">`:`<div class="ini">${esc(initials(p.name))}</div>`;
function bdInfo(p){if(!p.dob)return null;const t=new Date();t.setHours(0,0,0,0);const[y,m,d]=p.dob.split('-').map(Number);let n=new Date(t.getFullYear(),m-1,d);if(n<t)n=new Date(t.getFullYear()+1,m-1,d);return{days:Math.round((n-t)/864e5),age:n.getFullYear()-y}}
function renderBday(){const l=db.players.map(p=>({p,b:bdInfo(p)})).filter(x=>x.b&&x.b.days<=7).sort((a,b)=>a.b.days-b.b.days);
  $('#bday').hidden=!l.length;
  $('#bday').innerHTML=l.map(({p,b})=>`<div class="bi" data-prof="${p.id}"><span>🎂</span><div><b>${esc(p.name)}</b><small>${b.days===0?'Today! Turns '+b.age+' 🎉':b.days===1?'Tomorrow · turns '+b.age:'In '+b.days+' days · turns '+b.age}</small></div>${b.days===0?`<button class="wish" data-wish="${p.id}">🎉 Wish</button>`:''}</div>`).join('')}
function checkBday(){const t0=db.players.filter(p=>{const b=bdInfo(p);return b&&b.days===0}),t1=db.players.filter(p=>{const b=bdInfo(p);return b&&b.days===1});
  if(!t0.length&&!t1.length)return;const k='bd_'+today();if(localStorage.getItem(k))return;localStorage.setItem(k,'1');
  $('#alertBox').innerHTML=`<div class="ph"><div style="font-size:60px">🎂</div><h2>${t0.length?'Birthday Today!':'Birthday Tomorrow'}</h2></div>`+
   t0.map(p=>`<div class="bi"><span>🎉</span><div><b>${esc(p.name)}</b><small>turns ${bdInfo(p).age} today</small></div><button class="wish" data-wish="${p.id}">🎉 Wish</button></div>`).join('')+
   t1.map(p=>`<div class="bi"><span>⏰</span><div><b>${esc(p.name)}</b><small>Tomorrow · turns ${bdInfo(p).age}</small></div></div>`).join('')+`<button class="gold" id="alOk">Super! 🎉</button>`;
  $('#mAlert').classList.add('show');$('#alOk').onclick=()=>$('#mAlert').classList.remove('show')}

function tabsHtml(){return CATS.map(c=>{const ps=plist(c),r=db.rec[rk($('#date').value,c)]||{};
  const P=ps.filter(p=>r[p.id]==='P').length,A=ps.filter(p=>r[p.id]==='A').length;
  return`<button data-cat="${c}" class="${c===cat?'on':''}">${c==='Junior'?'⚽':'🛡️'} ${c.toUpperCase()}<div class="chs"><span class="ch p">${P}P</span><span class="ch a">${A}A</span><span class="ch u">${ps.length-P-A}?</span></div></button>`}).join('')}
function renderAtt(){
  const ps=plist(cat),r=db.rec[rk()]||{},q=$('#q').value.toLowerCase(),d=$('#date').value;
  const tally=l=>{let P=0,A=0;l.forEach(p=>{const v=(db.rec[rk(d,p.cat)]||{})[p.id];if(v==='P')P++;else if(v==='A')A++});return{P,A,U:l.length-P-A,T:l.length}};
  const g=tally(db.players),c=tally(ps);
  const tiles=(x,cl)=>`<div class="p"><b>${x.P}</b>PRESENT</div><div class="a"><b>${x.A}</b>ABSENT</div><div class="u"><b>${x.U}</b>UNMARKED</div><div><b>${x.T}</b>TOTAL</div>`;
  $('#sum').innerHTML=tiles(g);
  $('#tabs').innerHTML=tabsHtml();
  $('#ccard').innerHTML=`<div class="ct"><div class="ci">${cat==='Junior'?'⚽':'🛡️'}</div><div><h2>${cat.toUpperCase()}</h2><p>${c.T} players</p></div><div class="big">${c.P}<small>/${c.T}</small><p>Present today</p></div></div><div class="bar"><i style="width:${c.T?c.P/c.T*100:0}%"></i></div><div class="cg">${tiles(c)}</div>`;
  const row=p=>{const v=r[p.id]||'',b=bdInfo(p),sub=(p.no?'#'+esc(p.no):'')+(p.no&&p.pos?' · ':'')+esc(p.pos||'');
   return`<div class="pl ${v}"><div class="l">${avatar(p)}<div class="nm"><b>${esc(p.name)}${b&&b.days===0?' 🎂':''}</b>${sub?`<span>${sub}</span>`:''}</div></div>
   <button class="pf" data-prof="${p.id}"><em>👤</em></button>
   <button class="y ${v==='P'?'on':''}" data-m="${p.id}" data-v="P"><em>✓</em>YES</button>
   <button class="n ${v==='A'?'on':''}" data-m="${p.id}" data-v="A"><em>✕</em>NO</button></div>`};
  const f=ps.filter(p=>p.name.toLowerCase().includes(q));
  const sec=(t,k)=>{const a=f.filter(p=>(r[p.id]||'')===k);return a.length?`<div class="sec">— ${t} · ${a.length}</div>`+a.map(row).join(''):''};
  $('#list').innerHTML=(sec('PRESENT','P')+sec('ABSENT','A')+sec('UNMARKED',''))||(cloudOn()&&!gotP?'<div class="empty">⏳ Cloud la irundhu players load aaguthu...<br><small>Login screen vandha login pannunga</small></div>':'<div class="empty">No players. "＋ Player" click pannunga.</div>');
  renderBday();
}
function renderHis(){
  const ks=Object.keys(db.rec).filter(k=>Object.keys(db.rec[k]).length).sort().reverse();
  $('#hist').innerHTML=ks.map(k=>{const[d,c]=k.split('|'),v=Object.values(db.rec[k]),P=v.filter(x=>x==='P').length;
    return`<div class="hs" data-k="${k}"><div><b>${fmt(d)}</b><small>${c}</small></div><span class="tag">${P} Present</span><span class="tag">${v.length-P} Absent</span></div>`}).join('')||'<div class="empty">No sessions saved yet</div>';
}
function stats(p,f='0000-01-01',t='9999-12-31'){let P=0,A=0,h=[];
  Object.keys(db.rec).filter(k=>k.endsWith('|'+p.cat)).sort().forEach(k=>{const d=k.split('|')[0];if(d<f||d>t)return;const v=db.rec[k][p.id];if(v){v==='P'?P++:A++;h.push([d,v])}});
  return{P,A,h,pct:P+A?Math.round(P/(P+A)*100):0}}
function renderRep(){
  $('#rtabs').innerHTML=CATS.map(c=>`<button data-cat="${c}" class="${c===cat?'on':''}">${c.toUpperCase()}</button>`).join('');
  $('#rf').value=rf.from.startsWith('0000')?'':rf.from;$('#rt').value=rf.to.startsWith('9999')?'':rf.to;
  const ks=sessionsIn(cat),a=plist(cat).map(p=>({p,s:stats(p,rf.from,rf.to)})).sort((x,y)=>y.s.pct-x.s.pct||y.s.P-x.s.P);
  const avg=a.length?Math.round(a.reduce((t,x)=>t+x.s.pct,0)/a.length):0;
  $('#rsum').innerHTML=`<div><b>${ks.length}</b>SESSIONS</div><div class="p"><b>${avg}%</b>AVG ATTENDANCE</div><div class="u"><b>${a[0]&&a[0].s.P+a[0].s.A?esc(a[0].p.name.split(' ')[0]):'-'}</b>TOP PLAYER</div>`;
  $('#rep').innerHTML=a.map(({p,s},i)=>`<div class="rr" data-prof="${p.id}"><span class="medal">${['🥇','🥈','🥉'][i]||i+1}</span>${avatar(p)}<div class="l2"><b>${esc(p.name)}</b><small>${s.P} present · ${s.A} absent</small><div class="bar"><i style="width:${s.pct}%"></i></div></div><div class="pc">${s.pct}%</div></div>`).join('')||'<div class="empty">No players</div>';
}
function render(){view==='att'?renderAtt():view==='his'?renderHis():renderRep()}
function setView(v){view=v;['att','his','rep'].forEach(x=>$('#v-'+x).hidden=x!==v);
  document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===v));
  $('.live').hidden=v!=='att';render()}

$('#nav').onclick=e=>{const b=e.target.closest('button');if(b)setView(b.dataset.v)};
const tabClick=e=>{const b=e.target.closest('button');if(b){cat=b.dataset.cat;render()}};
$('#tabs').onclick=tabClick;$('#rtabs').onclick=tabClick;
$('#date').onchange=render;$('#q').oninput=renderAtt;
$('#hist').onclick=e=>{const h=e.target.closest('[data-k]');if(!h)return;const[d,c]=h.dataset.k.split('|');$('#date').value=d;cat=c;setView('att')};
const profClick=e=>{const p=e.target.closest('[data-prof]');if(p)profile(p.dataset.prof)};
$('#list').onclick=e=>{
  const m=e.target.closest('[data-m]');
  if(m){const k=rk();db.rec[k]=db.rec[k]||{};const id=m.dataset.m,v=m.dataset.v;
    if(db.rec[k][id]===v)delete db.rec[k][id];else db.rec[k][id]=v;
    if(!Object.keys(db.rec[k]).length)delete db.rec[k];save();sync();renderAtt();return}
  profClick(e)};
$('#rep').onclick=profClick;
const setAll=v=>{const k=rk();db.rec[k]=db.rec[k]||{};plist(cat).forEach(p=>{if(v)db.rec[k][p.id]=v;else delete db.rec[k][p.id]});
  if(!Object.keys(db.rec[k]).length)delete db.rec[k];save();sync();renderAtt()};
$('#allP').onclick=()=>setAll('P');$('#allA').onclick=()=>setAll('A');
$('#rst').onclick=()=>ask('Indha session-a reset pannanuma?',()=>setAll(null));

// add/edit
function openAdd(p){editId=p?p.id:null;photoData=p?p.photo||'':'';
  $('#addT').textContent=p?'Edit Player':'Add Player';
  $('#pn').value=p?p.name:'';$('#pno').value=p?p.no:'';$('#ppos').value=p?p.pos:'';$('#pdob').value=p?p.dob||'':'';$('#pph').value=p?p.phone||'':'';$('#pcat').value=p?p.cat:cat;
  $('#pv').src=photoData||logo;$('#pv').classList.toggle('lgo',!photoData);$('#mAdd').classList.add('show')}
$('#add').onclick=()=>openAdd();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#mAdd').classList.remove('show'));
$('#photo').onchange=e=>{const f=e.target.files[0];if(!f)return;const img=new Image();
  img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=200;const s=Math.min(img.width,img.height);
    c.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,200,200);
    photoData=c.toDataURL('image/jpeg',.8);$('#pv').src=photoData;$('#pv').classList.remove('lgo')};img.src=URL.createObjectURL(f)};
$('#fAdd').onsubmit=e=>{e.preventDefault();
  const o={name:$('#pn').value.trim(),no:$('#pno').value,pos:$('#ppos').value.trim(),cat:$('#pcat').value,photo:photoData,dob:$('#pdob').value,phone:$('#pph').value.trim()};
  let pl;if(editId){pl=db.players.find(p=>p.id===editId);Object.assign(pl,o)}else{pl={id:'p'+Date.now(),...o};db.players.push(pl)}
  if(cloudOn())Cloud.savePlayer(pl);
  save();$('#mAdd').classList.remove('show');cat=o.cat;render()};

// profile
function profile(id){const p=db.players.find(x=>x.id===id),s=stats(p),b=bdInfo(p),age=b?(b.days===0?b.age:b.age-1):0;
  $('#prof').innerHTML=`<div class="ph"><img class="${p.photo?'':'lgo'}" src="${p.photo||logo}"><h2>${esc(p.name)}</h2><span>${p.no?'#'+esc(p.no)+' · ':''}${esc(p.pos||'')} · ${p.cat}</span>
  ${b?`<div class="dob">🎂 ${fmt(p.dob)} · ${age} yrs<br><small>${b.days===0?'🎉 Happy Birthday today!':'Birthday in '+b.days+' days'}</small></div>`:'<div class="dob none">Birthday not added · Edit to add</div>'}</div>
  <div class="pct">${s.pct}%</div><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div><b>${s.P+s.A}</b>SESSIONS</div><div class="p"><b>${s.P}</b>PRESENT</div><div class="a"><b>${s.A}</b>ABSENT</div></div>
  <div class="hist">${s.h.slice().reverse().map(([d,v])=>`<i class="${v}">${fmt(d)} · ${v==='P'?'✔':'✘'}</i>`).join('')||'<span class="empty">No records yet</span>'}</div>
  <div class="row2"><button class="ghost" id="pe">Edit</button><button class="ghost" id="pd">Delete</button><button class="gold" id="pc">Close</button></div>`;
  $('#mProf').classList.add('show');
  $('#pc').onclick=()=>$('#mProf').classList.remove('show');
  $('#pe').onclick=()=>{$('#mProf').classList.remove('show');openAdd(p)};
  $('#pd').onclick=()=>ask('Delete '+p.name+'?',()=>{db.players=db.players.filter(x=>x.id!==id);save();if(cloudOn())Cloud.delPlayer(id);$('#mProf').classList.remove('show');render()})}
$('#mProf').onclick=e=>{if(e.target.id==='mProf')e.target.classList.remove('show')};

// WhatsApp
const wa=t=>window.open('https://wa.me/?text='+encodeURIComponent(t),'_blank');
$('#exp').onclick=()=>{
  const ps=plist(cat),r=db.rec[rk()]||{};
  const pr=ps.filter(p=>r[p.id]==='P'),ab=ps.filter(p=>r[p.id]==='A'),un=ps.filter(p=>!r[p.id]);
  const L=a=>a.map((p,i)=>`${i+1}. ${p.name}${p.no?' (#'+p.no+')':''}`).join('\n')||'-';
  let t=`🏆 *LEGIONS FC – ${cat} Attendance*\n📅 ${fmt($('#date').value)}\n\n✅ *Present (${pr.length})*\n${L(pr)}\n\n❌ *Absent (${ab.length})*\n${L(ab)}`;
  if(un.length)t+=`\n\n⚪ *Not marked (${un.length})*\n${L(un)}`;
  wa(t+`\n\n📊 ${pr.length}/${ps.length} present`)};


// ---- Reports ----
const ms=()=>today().slice(0,8)+'01';
let rf={from:ms(),to:today()};
function sessionsIn(c){return Object.keys(db.rec).filter(k=>{const[d,cc]=k.split('|');return cc===c&&d>=rf.from&&d<=rf.to&&Object.keys(db.rec[k]).length}).sort()}
document.querySelector('.chips').onclick=e=>{const b=e.target.closest('[data-r]');if(!b)return;const r=b.dataset.r;
  if(r==='month')rf={from:ms(),to:today()};
  else if(r==='30'){const d=new Date();d.setDate(d.getDate()-30);rf={from:new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,10),to:today()}}
  else rf={from:'0000-01-01',to:'9999-12-31'};renderRep()};
$('#rf').onchange=()=>{rf.from=$('#rf').value||'0000-01-01';renderRep()};
$('#rt').onchange=()=>{rf.to=$('#rt').value||'9999-12-31';renderRep()};
$('#repWa').onclick=()=>wa(`🏆 *LEGIONS FC – ${cat} Report*\n📅 ${rf.from.startsWith('0000')?'Start':fmt(rf.from)} → ${rf.to.startsWith('9999')?'Today':fmt(rf.to)}\n\n`+plist(cat).map(p=>({p,s:stats(p,rf.from,rf.to)})).sort((a,b)=>b.s.pct-a.s.pct).map(({p,s},i)=>`${i+1}. ${p.name} – ${s.pct}% (${s.P}P/${s.A}A)`).join('\n'));
$('#csv').onclick=()=>{const ks=sessionsIn(cat),ps=plist(cat);
  const rows=[['Name','Jersey','Position',...ks.map(k=>k.split('|')[0]),'Present','Absent','%']];
  ps.forEach(p=>{const s=stats(p,rf.from,rf.to);rows.push([p.name,p.no||'',p.pos||'',...ks.map(k=>db.rec[k][p.id]||'-'),s.P,s.A,s.pct+'%'])});
  const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n');
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Legions_'+cat+'_report.csv';a.click()};
$('#prt').onclick=()=>window.print();

// ---- Cloud hooks ----
window.App={setData(p,r){if(p){db.players=p;gotP=true}if(r)db.rec=r;render();checkBday()},setUser(e){$('#cuser').textContent=e?'☁ '+e:''}};
$('#logout').onclick=()=>window.Cloud&&Cloud.logout();
$('#upl').onclick=()=>ask('Indha device la irukkura pazhaya data-va cloud ku upload pannanuma?',()=>Cloud.uploadAll(JSON.parse(localStorage.getItem(KEY)||'{"players":[],"rec":{}}')));

// ---- Install (desktop / mobile) ----
let dp;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
if(standalone)localStorage.setItem('legions_inst','1');
$('#inst').hidden=!!localStorage.getItem('legions_inst');
addEventListener('beforeinstallprompt',e=>{e.preventDefault();dp=e;localStorage.removeItem('legions_inst');$('#inst').hidden=false});
$('#inst').onclick=async()=>{if(dp){dp.prompt();await dp.userChoice;dp=null;return}
  const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);
  $('#alertBox').innerHTML=`<div class="ph"><div style="font-size:42px">📲</div><h2>Install app</h2></div><p style="text-align:center;color:#cfc6a8;line-height:1.7">${ios?'Safari → Share ⬆ → <b>Add to Home Screen</b>':'Browser menu <b>⋮</b> → <b>Install app</b> / <b>Add to Home screen</b>'}</p><button class="gold" id="alOk">OK</button>`;
  $('#mAlert').classList.add('show');$('#alOk').onclick=()=>$('#mAlert').classList.remove('show')};
addEventListener('appinstalled',()=>{localStorage.setItem('legions_inst','1');$('#inst').hidden=true});

function ask(msg,yes){$('#alertBox').innerHTML=`<div class="ph"><div style="font-size:42px">⚠️</div><h2>${esc(msg)}</h2></div><div class="row2"><button class="ghost" id="aNo">Cancel</button><button class="gold" id="aYes">OK</button></div>`;
  $('#mAlert').classList.add('show');$('#aNo').onclick=()=>$('#mAlert').classList.remove('show');$('#aYes').onclick=()=>{$('#mAlert').classList.remove('show');yes()}}
document.querySelectorAll('img.logo').forEach(i=>i.src=LOGO);
const setZoom=z=>{document.body.style.zoom=z;localStorage.setItem('legions_zoom',z);document.querySelectorAll('#zs [data-z]').forEach(b=>b.classList.toggle('on',b.dataset.z===z))};
$('#zs').onclick=e=>{const b=e.target.closest('[data-z]');if(b)setZoom(b.dataset.z)};
setZoom(localStorage.getItem('legions_zoom')||'0.9');
function wishMsg(n){n=n.trim().replace(/\s+/g,' ');if(n===n.toUpperCase())n=n.toLowerCase().replace(/(^|\s)\S/g,c=>c.toUpperCase());return `🎉 Happy Birthday, ${n}! 🎂

Wishing you a wonderful birthday and a year filled with happiness, good health, success, and memorable achievements. May you continue to grow, learn, and excel in everything you do. Have a fantastic day and a bright future ahead.

Best Wishes,
LEGIONS FC ⚽✨`}
function wishP(p){const d=(p.phone||'').replace(/\D/g,''),num=d.length===10?'91'+d:d;window.open('https://wa.me/'+num+'?text='+encodeURIComponent(wishMsg(p.name)),'_blank')}
$('#alertBox').onclick=e=>{const w=e.target.closest('[data-wish]');if(w)wishP(db.players.find(x=>x.id===w.dataset.wish))};
$('#bday').onclick=e=>{const w=e.target.closest('[data-wish]');if(w){const p=db.players.find(x=>x.id===w.dataset.wish);wishP(p);return}const c=e.target.closest('[data-prof]');if(c)profile(c.dataset.prof)};
render();checkBday();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
